use xiom.io;
fn play_round(secret: Int) -> Int {
  var low = 1;
  var high = 100;
  var attempts = 0;
  while low <= high {
    let guess = (low + high) / 2;
    attempts += 1;
    if guess == secret {
      return attempts;
    };
    if guess < secret {
      low = guess + 1;
    } else {
      high = guess - 1;
    };
  };
  attempts
}

fn calculate_score(attempts: Int) -> Int {
  let score = (7 - attempts + 1) * 100 / 7;
  if score < 0 { return 0; };
  score
}

fn main() -> Int {
  let secret = 42;
  let attempts = play_round(secret);
  io.println(attempts.to_str());
  io.println(calculate_score(attempts).to_str());
  return 0;
}
